//! 🔐️ Invalid consuming decoder receipts remain in their original receiving slot.
use crate::ValueError;
use semio_framework_test_fixtures::fixture_text;
fn fixture()->serde_json::Value{serde_json::from_str(fixture_text!("../../🫴️recipient/🔁️continuation/🧪️tests/🧫️fixtures/🔣️.json")).unwrap()}
#[test]fn native_local_original_invalid_decode_receipt_is_not_consumed(){let law=fixture();let mut recipient=super::NativeDecodeRetirementRecipient::new();let mut observer=|_|true;let mut native=super::NativeDecodeControl::new(law["maximumNativeBytes"].as_u64().unwrap()as usize,&mut observer);native.charge(law["initialBytes"].as_u64().unwrap()as usize).unwrap();let mut receipt=native.pause().unwrap();receipt.completed=law["invalidReceipt"]["completed"].as_u64().unwrap()as usize;receipt.total=law["invalidReceipt"]["total"].as_u64().unwrap()as usize;let mut receipt=super::NativeRetirementDecodeContinuation{receipt:Some(receipt),recipient:&mut recipient};let before=receipt.owned_bytes();let mut accepted=|_|true;let error=receipt.decode::<(),ValueError>(&mut accepted,None,|_|Ok(())).unwrap_err();assert_eq!(error.context.unwrap().kind.as_str(),law["invalidReceipt"]["kind"].as_str().unwrap());assert_eq!(receipt.owned_bytes(),before);let(detached,_)=receipt.detach();assert_eq!(detached.owned_bytes(),before);}
#[test]fn original_decode_envelope_keeps_result_and_context_refusal(){
 let law=fixture();for fail in [true,false]{
  let mut recipient=super::NativeDecodeRetirementRecipient::new();let mut progress=|_|true;let receipt=super::NativeDecodeControl::new_retained(&mut progress).pause().unwrap();let mut continuation=receipt.with_retirement_recipient(&mut recipient).map_err(|(error,_)|error).unwrap();let mut progress=|_|true;let mut authority=crate::OriginalWorkAuthority::new(crate::eff::Producer{maximum:1});
  let value=law["callEnvelope"][if fail{"operation"}else{"output"}].as_str().unwrap().to_owned();let pointer=value.as_ptr();
  let result=authority.with_loan(&mut (),|loan|continuation.decode::<String,ValueError>(&mut progress,None,|control|control.with_work_recipient(loan,|original|{assert!(original.prepare_work(1)?);original.depth=1;if fail{Err(ValueError::new(crate::ValueRefusalKind::InvalidValue,value))}else{Ok(value)}}))).unwrap();
  assert_eq!(continuation.pending_work(),1);assert!(continuation.has_pending_work());
  let failure=result.unwrap_err();if fail{assert_eq!(failure.operation.as_ref().unwrap().message.as_ptr(),pointer);assert!(failure.output.is_none())}else{assert_eq!(failure.output.as_ref().unwrap().as_ptr(),pointer);assert!(failure.operation.is_none())}assert_eq!(failure.context.as_ref().unwrap().message.to_string(),law["callEnvelope"]["context"].as_str().unwrap());
  authority.with_loan(&mut (),|loan|continuation.decode::<(),ValueError>(&mut progress,None,|control|control.with_work_recipient(loan,|control|control.commit_work(1)))).unwrap().unwrap();assert!(!continuation.has_pending_work());let(_receipt,_recipient)=continuation.detach();assert!(authority.into_recipient().is_ok());
 }
}
